			string content = null;
			string description = null;
			bool isEnable = false;

			switch ((BattleEffectIndex)index)
			{
				case BattleEffectIndex.TOKUSEI:
				{
					var tokuseiNo = btlParam.GetSrcData().GetTokuseiNo();
					if (tokuseiNo != Pml.TokuseiNo.NULL)
					{
						name = BattleStr.Instance.GetFormatUIText("msg_ui_btl_wazainfo_tokusei");
						Dpr.Message.MessageWordSetHelper.SetTokuseiWord(0, tokuseiNo);
						content = BattleStr.Instance.GetFormatUIText("msg_ui_btl_wazainfo_tokuseiname");
						description = BattleStr.GetTokuseiInfo(tokuseiNo);
						isEnable = true;
					}
					break;
				}

				case BattleEffectIndex.ITEM:
				{
					ushort itemNo = btlParam.GetItem();
					if (itemNo != 0)
					{
						name = BattleStr.Instance.GetFormatUIText("msg_ui_btl_wazainfo_item");
						Dpr.Message.MessageWordSetHelper.SetItemWord(0, itemNo, 1);
						content = BattleStr.Instance.GetFormatUIText("msg_ui_btl_wazainfo_itemname");
						description = Dpr.Message.MessageManager.Instance.GetSimpleMessage("ss_iteminfo", itemNo);
						isEnable = true;
					}
					break;
				}

				default:
					return;
			}

			_statusTexts.Add((name, content, description));
			_itemButtons[index].SetActive(isEnable);
			_itemButtons[index].Initialize(_statusTexts[index].name, _statusTexts[index].content);
			if (!isEnable && CurrentIndex == index)
				CurrentIndex = index + 1;
		}
